/* ===== ephemeral UI state ===== */
const UI={view:'list',radius:6,exTab:'shops',exCat:'',q:'',stab:'p',fl:{cat:'',dist:0,rating:0,open:false,offers:false,deliver:false,pickup:false,pmin:'',pmax:''},sort:'relevance',btab:'about',stab2:'about',pvar:{},pqty:1,sel:'',cotab:'',orders:'active',saveTab:'b',carT:0};
const shareUrl=id=>location.href.split('#')[0]+'#'+id;
const mapsDir=x=>`https://www.google.com/maps/dir/?api=1&destination=${x.lat},${x.lng}`;
const telH=n=>'tel:+91'+String(n).replace(/\D/g,'').slice(-10),waH=(n,m)=>'https://wa.me/91'+String(n).replace(/\D/g,'').slice(-10)+(m?'?text='+encodeURIComponent(m):'');
const rec=id=>{S.recent=[id,...S.recent.filter(x=>x!==id)].slice(0,12);save()};
const isBm=id=>S.bookmarks.includes(id);
A.bm=el=>{if(needLogin('Log in to save your favourite shops and services.'))return;const id=el.dataset.id;S.bookmarks=isBm(id)?S.bookmarks.filter(x=>x!==id):[...S.bookmarks,id];save();render(true);toast(isBm(id)?t('Saved to bookmarks'):t('Removed from bookmarks'),'bookmark')};
A.share=el=>{const id=el.dataset.id,e=ent(id),u=shareUrl(routeFor(id));const txt=nm(e.name)+' on ApnaTown';sheet(`<h3>${t('Share')}</h3><p class="small muted">${esc(nm(e.name))}</p><div class="stack" style="margin-top:10px"><a class="btn s block" target="_blank" rel="noopener" href="${waH('',txt+' '+u).replace('/91','/')}">${ic('chat',18)} WhatsApp</a><button class="btn g block" data-act="copy" data-v="${esc(u)}">${ic('copy',18)} ${t('Copy link')}</button><div class="field"><input class="input" readonly value="${esc(u)}" aria-label="Link"></div></div>`,{label:'Share'})};
A.copy=el=>{const v=el.dataset.v;try{navigator.clipboard.writeText(v).then(()=>toast(t('Link copied')),()=>toast(t('Copy: ')+v,'info'))}catch(e){toast(v,'info')}};
/* QR */
function qrSvg(text,emoji){let svg='';try{const q=qrcode(0,'M');q.addData(text);q.make();svg=q.createSvgTag({cellSize:5,margin:2,scalable:true})}catch(e){svg=`<div class="pre">${esc(text)}</div>`}
 return `<div style="position:relative;width:210px;height:210px;background:#fff;padding:8px;border-radius:12px;color:#000">${svg.replace('<svg','<svg class="qr" style="width:194px;height:194px;display:block;background:#fff"')}<div style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:44px;height:44px;border-radius:50%;background:#fff;display:grid;place-items:center;font-size:24px;border:2px solid #C2410C">${emoji||'🏪'}</div></div>`}
/* ===== splash / onboarding ===== */
function splash(){sheet(`<div class="stack center" style="padding-bottom:8px"><div style="font-size:3rem">🏪</div><h1>Apna<span style="color:var(--primary)">Town</span>.in</h1><p class="t2">${S.lang==='hi'?'आपके शहर का अपना बाज़ार':'Your town’s own bazaar, now online'}</p><div class="lbl">${t('Choose your language')} / भाषा चुनें</div><div class="grid g2"><button class="btn ${S.lang==='en'?'p':'g'} block" data-act="setLang" data-v="en">English</button><button class="btn ${S.lang==='hi'?'p':'g'} block" data-act="setLang" data-v="hi">हिन्दी</button></div><button class="btn p block" data-act="splashNext">${t('Continue')}</button></div>`,{label:'Welcome',nofocus:true})}
A.setLang=el=>{S.lang=el.dataset.v;save();splash();render(true)};
A.splashNext=()=>{S.splash=true;save();sheet(`<div class="stack center"><div style="font-size:3rem">📍</div><h3>${t('Find shops near you')}</h3><p class="t2">${t('Allow location to see distance and delivery options. You can browse without it.')}</p><button class="btn p block" data-act="gps">${t('Allow location')}</button><button class="btn o block" data-act="loc">${t('Choose area manually')}</button><button class="btn t" data-act="closeSheet">${t('Skip for now')}</button></div>`,{label:'Location'})};
/* ===== HOME ===== */
function bannerStrip(){const b=D().banners.filter(x=>x.on);return `<div><div class="hero" id="hero" tabindex="0" aria-label="${t('Promotions')}">${b.map(x=>`<div class="slide" style="--c1:${x.c1};--c2:${x.c2}"><h2>${esc(x.t)}</h2><p>${esc(x.s)}</p><a class="btn sm" href="#${x.link}">${t('Shop now')}</a></div>`).join('')}</div><div class="dots" id="herodots">${b.map((_,i)=>`<i class="${i?'':'on'}"></i>`).join('')}</div></div>`}
V.home=()=>{
 post.push(()=>{initLazy();if(!S.splash)splash();const h=$('#hero');if(!h)return;clearInterval(UI.carT);let i=0;const n=h.children.length;const upd=()=>{const k=Math.round(h.scrollLeft/h.clientWidth);$$('#herodots i').forEach((d,j)=>d.classList.toggle('on',j===k))};h.addEventListener('scroll',upd,{passive:true});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)UI.carT=setInterval(()=>{if(!document.contains(h))return clearInterval(UI.carT);i=(i+1)%n;h.scrollTo({left:i*h.clientWidth,behavior:'smooth'})},4500)});
 const D_=D(),open=x=>x.status==='approved';const near=[...D_.biz.filter(open)].sort((a,b)=>dist(a)-dist(b));const feat=D_.biz.filter(b=>open(b)&&b.featured),pop=D_.biz.filter(b=>open(b)&&b.popular),fp=D_.products.filter(p=>p.featured&&p.avail&&biz(p.bid).status==='approved').slice(0,8);
 const ofs=D_.offers.filter(o=>o.status==='active'&&Date.now()<o.to);const rv=S.recent.map(ent).filter(Boolean).slice(0,6);const bms=S.bookmarks.map(ent).filter(Boolean).slice(0,4);
 return `<div class="stack-lg">${bannerStrip()}
 <section aria-label="${t('Product categories')}"><div class="sec" style="margin-top:0"><h2>${t('Shop by category')}</h2><a class="btn t sm" href="#explore">${t('See all')} ${ic('cr',16)}</a></div><div class="grid g4" style="grid-template-columns:repeat(auto-fill,minmax(84px,1fr))">${D_.cats.filter(c=>c.on).map(c=>`<a class="tile" href="#explore" data-act="catGo" data-id="${c.id}">${art(c.e,c.h)}<span>${esc(nm(c))}</span></a>`).join('')}</div></section>
 <section><div class="sec" style="margin-top:0"><h2>${t('Local services')}</h2><a class="btn t sm" href="#services">${t('See all')} ${ic('cr',16)}</a></div><div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(84px,1fr))">${D_.scats.filter(c=>c.on).map(c=>`<a class="tile" href="#explore" data-act="catGo" data-id="${c.id}">${art(c.e,c.h)}<span>${esc(nm(c))}</span></a>`).join('')}</div></section>
 <section>${sec('Offers & deals','offers')}<div class="hscroll wide">${ofs.map(o=>{const b=biz(o.bid);return `<button class="card pad hover" data-act="offerGo" data-id="${o.id}" style="text-align:left;background:linear-gradient(135deg,var(--offer-soft),var(--surface))"><div class="row"><span class="badge offer">${ic('tag',13)} ${o.type==='percent'?o.value+'% '+t('OFF'):o.type==='flat'?'₹'+o.value+' '+t('OFF'):t('Free delivery')}</span></div><h3 style="margin:8px 0 4px">${esc(o.title)}</h3><div class="small t2">${esc(nm(b.name))} · ${t('till')} ${fdate(o.to)}</div></button>`}).join('')||empty('🏷️','No offers right now','Check back soon.')}</div></section>
 <section>${secBtn('Nearby shops','View all shops','b',{sort:'distance'})}<div class="shopgrid">${near.slice(0,8).map(shopCard).join('')}</div></section>
 <section>${secBtn('Featured businesses','View all businesses','b',{featured:true})}<div class="hscroll wide">${feat.map(b=>bizCard(b,true)).join('')}</div></section>
 <section>${sec('Popular businesses','explore')}<div class="hscroll wide">${pop.map(b=>bizCard(b,true)).join('')}</div></section>
 <section>${secBtn('Featured products','View all products','p',{featured:true})}<div class="hscroll">${fp.map(prodCard).join('')}</div></section>
 <section>${sec('Popular service providers','services')}<div class="grid auto">${D_.svc.filter(s=>s.status==='approved'&&(s.popular||s.featured)).slice(0,4).map(s=>svcCard(s)).join('')}</div></section>
 <section><div class="card pad row" style="background:var(--secondary-soft);border-color:transparent"><div class="mini art" style="--h:170">📣</div><div class="grow"><b>${t('Local promotions')}</b><div class="small t2">${t('Shops in your area run weekly specials. Check the offers page.')}</div></div><a class="btn s sm" href="#offers">${t('View')}</a></div></section>
 ${rv.length?`<section>${sec('Recently viewed')}<div class="hscroll">${rv.map(e=>e.id[0]==='p'?prodCard(e):e.id[0]==='s'?svcCard(e,true):bizCard(e,true)).join('')}</div></section>`:''}
 ${bms.length?`<section>${sec('Your bookmarks','bookmarks')}<div class="grid auto">${bms.map(e=>e.id[0]==='s'?svcCard(e):bizCard(e)).join('')}</div></section>`:''}</div>`};
/* ===== categories / services ===== */
V.services=()=>`<div class="stack-lg"><h1>${t('Local services')}</h1><div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(110px,1fr))">${D().scats.filter(c=>c.on).map(c=>`<a class="tile card" href="#cat-${c.id}">${art(c.e,c.h)}<span>${esc(nm(c))}</span></a>`).join('')}</div>${sec('Popular service providers')}<div class="grid auto">${D().svc.filter(s=>s.status==='approved').map(s=>svcCard(s)).join('')}</div></div>`;
V.cat=id=>{const c=catOf(id),isS=SCATS.some(x=>x.id===id);const list=isS?D().svc.filter(s=>s.cat===id&&s.status==='approved'):D().biz.filter(b=>b.cat===id&&b.status==='approved');const prods=isS?[]:D().products.filter(p=>p.cat===id&&biz(p.bid).status==='approved');list.sort((a,b)=>dist(a)-dist(b));
 return `<div class="stack-lg"><div class="crumb"><a href="#home">${t('Home')}</a> / <span>${esc(nm(c))}</span></div><div class="row"><div class="art mini" style="--h:${c.h}">${c.e}</div><h1>${esc(nm(c))}</h1></div>${list.length?`<div class="grid auto">${list.map(x=>isS?svcCard(x):bizCard(x)).join('')}</div>`:empty('🏪','No listings yet','Be the first to list here.','<a class="btn p" href="#vonboard" data-act="asRole" data-role="vendor">'+t('Add your business')+'</a>')}${prods.length?sec('Products')+`<div class="grid auto-s">${prods.map(prodCard).join('')}</div>`:''}</div>`};
/* ===== EXPLORE (map/list) ===== */
function exploreItems(){const q=UI.exTab==='shops'?D().biz:D().svc;let l=q.filter(x=>x.status==='approved'&&dist(x)<=UI.radius);if(UI.exCat)l=l.filter(x=>x.cat===UI.exCat);return l.sort((a,b)=>dist(a)-dist(b))}
V.explore=()=>{const l=exploreItems(),cats=UI.exTab==='shops'?D().cats:D().scats;const sel=l.find(x=>x.id===UI.sel);
 const mapH=`${mapSvg('exmap',l,{radius:UI.radius,sel:UI.sel})}${sel?`<div class="mapcard card pad row"><div class="mini art" style="--h:${sel.hue}">${sel.emoji}</div><div class="grow"><b>${esc(nm(sel.name))}</b><div class="small t2">${dist(sel).toFixed(1)} km · ${esc(areaName(sel.area))}</div></div><a class="btn p sm" href="#${sel.id[0]==='s'?'svc':'biz'}-${sel.id}">${t('View')}</a><a class="btn g sm" target="_blank" rel="noopener" href="${mapsDir(sel)}">${ic('nav',16)}</a></div>`:''}`;
 return `<div class="stack"><div class="row between"><h1>${t('Explore nearby')}</h1><div class="row"><button class="chip ${UI.view==='list'?'on':''}" data-act="exview" data-v="list">${ic('list',16)} ${t('List')}</button><button class="chip ${UI.view==='map'?'on':''}" data-act="exview" data-v="map">${ic('map',16)} ${t('Map')}</button></div></div>
 <div class="tabs" role="tablist"><button role="tab" class="${UI.exTab==='shops'?'on':''}" data-act="extab" data-v="shops">${t('Shops')}</button><button role="tab" class="${UI.exTab==='services'?'on':''}" data-act="extab" data-v="services">${t('Services')}</button></div>
 <div class="chips"><button class="chip ${UI.exCat?'':'on'}" data-act="excat" data-v="">${t('All')}</button>${cats.map(c=>`<button class="chip ${UI.exCat===c.id?'on':''}" data-act="excat" data-v="${c.id}">${c.e} ${esc(nm(c))}</button>`).join('')}</div>
 <div class="card pad"><label class="row between small" for="rad"><b>${t('Distance')}: ${t('within')} ${UI.radius} km</b></label><input id="rad" type="range" min="1" max="12" step="1" value="${UI.radius}" data-in="radius" style="width:100%;accent-color:var(--primary)" aria-label="${t('Distance radius')}"></div>
 ${alertBox('info',`<b>${t('Nearby')}</b> = ${t('how far the shop is from')} ${esc(S.loc.name)}. <b>${t('Delivers to you')}</b> = ${t('the shop delivers to your selected address.')}`)}
 ${UI.view==='map'?`<div style="position:relative">${mapH}</div><div class="small muted">${l.length} ${t('places within')} ${UI.radius} km</div>`:''}
 ${l.length?`<div class="grid auto">${l.map(x=>UI.exTab==='shops'?bizCard(x):svcCard(x)).join('')}</div>`:empty('🔍','Nothing within this distance','Try a bigger radius or another category.','<button class="btn p" data-act="widen">'+t('Widen search')+'</button>')}</div>`};
A.exview=el=>{UI.view=el.dataset.v;render(true)};A.extab=el=>{UI.exTab=el.dataset.v;UI.exCat='';UI.sel='';render(true)};A.excat=el=>{UI.exCat=el.dataset.v;render(true)};A.widen=()=>{UI.radius=12;render(true)};
INP.radius=v=>{UI.radius=+v;clearTimeout(UI.rt);UI.rt=setTimeout(()=>render(true),120)};
A.mapPin=el=>{UI.sel=el.dataset.id;render(true)};
/* ===== SEARCH ===== */
const POPULAR=['atta','medicine','mobile charger','electrician','sweets','coaching'];
function runSearch(){const q=UI.q.trim().toLowerCase(),f=UI.fl;const mt=(...a)=>!q||a.join(' ').toLowerCase().includes(q);
 let b=D().biz.filter(x=>x.status==='approved'&&(mt(x.name.en,x.name.hi,catName(x.cat),x.desc,areaName(x.area))||D().products.some(p=>p.bid===x.id&&mt(p.name.en))&&!!q&&false));
 let p=D().products.filter(x=>biz(x.bid).status==='approved'&&mt(x.name.en,x.name.hi,catName(x.cat),biz(x.bid).name.en));
 let s=D().svc.filter(x=>x.status==='approved'&&mt(x.name.en,x.name.hi,catName(x.cat),x.desc,x.services.map(y=>y.n).join(' ')));
 if(f.cat){b=b.filter(x=>x.cat===f.cat);p=p.filter(x=>x.cat===f.cat);s=s.filter(x=>x.cat===f.cat)}
 if(f.dist){b=b.filter(x=>dist(x)<=f.dist);s=s.filter(x=>dist(x)<=f.dist);p=p.filter(x=>dist(biz(x.bid))<=f.dist)}
 if(f.rating){b=b.filter(x=>x.rating>=f.rating);s=s.filter(x=>x.rating>=f.rating);p=p.filter(x=>biz(x.bid).rating>=f.rating)}
 if(f.open){b=b.filter(x=>openState(x).open);s=s.filter(x=>openState(x).open);p=p.filter(x=>openState(biz(x.bid)).open)}
 if(f.offers){const ob=new Set(D().offers.filter(o=>o.status==='active').map(o=>o.bid));b=b.filter(x=>ob.has(x.id));p=p.filter(x=>ob.has(x.bid))}
 if(f.deliver){b=b.filter(x=>delivInfo(x).ok);p=p.filter(x=>delivInfo(biz(x.bid)).ok)}
 if(f.pickup){b=b.filter(x=>x.del.pickup);p=p.filter(x=>biz(x.bid).del.pickup)}
 if(f.pmin!=='')p=p.filter(x=>x.price>=+f.pmin);if(f.pmax!=='')p=p.filter(x=>x.price<=+f.pmax);
 s=svcApplyCS(s,UI.exF.s);const so=UI.sort;const cmpB=so==='distance'||so==='relevance'?(a,c)=>dist(a)-dist(c):so==='rating'?(a,c)=>c.rating-a.rating:so==='newest'?(a,c)=>(c.since||0)-(a.since||0):0;
 if(cmpB){b.sort(cmpB);s.sort(cmpB)}
 if(so==='plow')p.sort((a,c)=>a.price-c.price);else if(so==='phigh')p.sort((a,c)=>c.price-a.price);else if(so==='rating')p.sort((a,c)=>biz(c.bid).rating-biz(a.bid).rating);else if(so==='distance')p.sort((a,c)=>dist(biz(a.bid))-dist(biz(c.bid)));else if(so==='newest')p.sort((a,c)=>(+c.id.slice(1))-(+a.id.slice(1)));
 return{b,p,s}}
const fcount=()=>Object.entries(UI.fl).filter(([k,v])=>v&&v!==''&&v!==0).length;
function resultsHtml(){const r=runSearch(),tab=UI.stab,l=r[tab==='b'?'b':tab==='p'?'p':'s'];const q=UI.q.trim();
 if(!q&&!fcount())return `<div class="stack"><div><div class="lbl small">${t('Recent searches')}</div><div class="chips">${S.recentSearch.map(x=>`<button class="chip" data-act="sq" data-v="${esc(x)}">${ic('clock',14)} ${esc(x)}</button>`).join('')}</div></div><div><div class="lbl small">${t('Popular searches')}</div><div class="chips">${POPULAR.map(x=>`<button class="chip" data-act="sq" data-v="${esc(x)}">${ic('search',14)} ${esc(t(x))}</button>`).join('')}</div></div></div>`;
 const tabs=`<div class="tabs" role="tablist">${[['p','Products',r.p.length],['b','Businesses',r.b.length],['s','Services',r.s.length]].map(([k,lb,n])=>`<button role="tab" class="${tab===k?'on':''}" data-act="stab" data-v="${k}">${t(lb)} <span class="cnt" style="background:var(--surface-2);color:var(--text)">${n}</span></button>`).join('')}</div>`;
 if(!l.length){const sug=D().cats.slice(0,6);return tabs+empty('🔎','No results found','Try fewer filters or a different word.',`<div class="chips" style="justify-content:center;flex-wrap:wrap">${POPULAR.slice(0,4).map(x=>`<button class="chip" data-act="sq" data-v="${esc(x)}">${esc(t(x))}</button>`).join('')}</div>${fcount()?`<button class="btn o" data-act="clearFl">${t('Clear filters')}</button>`:''}`)}
 return tabs+`<div class="grid ${tab==='p'?'auto-s':'auto'}">${l.map(x=>tab==='b'?bizCard(x):tab==='p'?prodCard(x):svcCard(x)).join('')}</div>`}
function suggHtml(v){v=v.trim().toLowerCase();if(!v)return'';const g=[['Products',D().products.map(p=>p.name.en)],['Businesses',D().biz.map(b=>b.name.en)],['Services',D().svc.map(s=>s.name.en)]].map(([l,arr])=>[l,arr.filter(x=>x.toLowerCase().includes(v)).slice(0,3)]).filter(x=>x[1].length);return g.length?`<div class="card" role="listbox" aria-label="${t('Suggestions')}">${g.map(([l,a])=>`<div class="xs muted" style="padding:8px 14px 0">${t(l)}</div>`+a.map(x=>`<button class="btn t block" style="justify-content:flex-start;border-radius:0" role="option" data-act="sq" data-v="${esc(x)}">${ic('search',16)} ${esc(x)}</button>`).join('')).join('')}</div>`:''}
V.search=()=>{post.push(()=>{const i=$('#q');if(i&&!UI.q&&matchMedia('(pointer:fine)').matches)i.focus()});
 return `<div class="stack"><div class="searchbar">${ic('search',20)}<input id="q" type="search" value="${esc(UI.q)}" data-in="q" placeholder="${t('Search shops, products, services')}" aria-label="${t('Search')}" autocomplete="off"><button class="iconbtn" data-act="voice" aria-label="${t('Voice search')}">${ic('mic',20)}</button></div><div id="sugg"></div><div id="srchsf">${UI.stab==='s'?svcFilterCard('srch'):''}</div>
 <div class="row between"><button class="btn g sm" data-act="filters">${ic('filter',16)} ${t('Filters')}${fcount()?` <span class="cnt">${fcount()}</span>`:''}</button><div class="row"><label class="small muted" for="sort">${t('Sort')}</label><select id="sort" class="input" style="min-height:40px;width:auto" data-chg="sort">${[['relevance','Relevance'],['distance','Distance'],['rating','Rating'],['plow','Price: low to high'],['phigh','Price: high to low'],['newest','Newest']].map(([k,l])=>`<option value="${k}" ${UI.sort===k?'selected':''}>${t(l)}</option>`).join('')}</select></div></div>
 <div id="results">${resultsHtml()}</div></div>`};
INP.q=(v)=>{UI.q=v;$('#sugg').innerHTML=suggHtml(v);$('#results').innerHTML=resultsHtml()};
CH.sort=el=>{UI.sort=el.value;$('#results').innerHTML=resultsHtml()};
A.sq=el=>{UI.q=el.dataset.v;const q=UI.q.toLowerCase();S.recentSearch=[q,...S.recentSearch.filter(x=>x!==q)].slice(0,6);save();render(true);const i=$('#q');i&&i.blur()};
A.stab=el=>{UI.stab=el.dataset.v;$('#results').innerHTML=resultsHtml();$('#srchsf').innerHTML=UI.stab==='s'?svcFilterCard('srch'):''};
A.voice=()=>toast(t('Voice search needs microphone permission (demo)'),'mic');
A.clearFl=()=>{UI.fl={cat:'',dist:0,rating:0,open:false,offers:false,deliver:false,pickup:false,pmin:'',pmax:''};render(true)};
A.filters=()=>{const f=UI.fl;sheet(`<div class="row between"><h3>${t('Filters')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><form data-form="filters" class="stack" style="margin-top:10px">
 ${field('Category','cat',f.cat,{type:'select',opts:[['','All'],...CATS.map(c=>[c.id,c.en]),...SCATS.map(c=>[c.id,c.en])]})}
 ${field('Within distance','dist',f.dist,{type:'select',opts:[[0,'Any distance'],[1,'1 km'],[3,'3 km'],[5,'5 km'],[10,'10 km']]})}
 ${field('Minimum rating','rating',f.rating,{type:'select',opts:[[0,'Any'],[3,'3★ & up'],[4,'4★ & up'],[4.5,'4.5★ & up']]})}
 <div class="grid g2">${field('Min price (₹)','pmin',f.pmin,{type:'number',min:0,im:'numeric'})}${field('Max price (₹)','pmax',f.pmax,{type:'number',min:0,im:'numeric'})}</div>
 ${[['open','Open now'],['offers','Has offers'],['deliver','Delivers to my address'],['pickup','Self-pickup available']].map(([k,l])=>`<label class="check"><input type="checkbox" name="${k}" ${f[k]?'checked':''}>${t(l)}</label>`).join('')}
 <div class="row"><button type="button" class="btn g grow" data-act="clearFl">${t('Clear all')}</button><button class="btn p grow">${t('Apply')}</button></div></form>`,{label:'Filters'})};
